theorem cramer_conjecture (ε : ℝ) (hε : 0 < ε) :
    ∃ N : ℕ, ∀ n : ℕ, N ≤ n →
      let p := (Nat.nth Nat.Prime n : ℝ)
      let q := (Nat.nth Nat.Prime (n + 1) : ℝ)
      q - p < (1 + ε) * Real.log p ^ 2 := by
  sorry

